function generate(rand, size) {
  const clubs = ['Arsenal', 'Chelsea', 'Ajax', 'Porto', 'Lazio', 'Benfica'];
  const pick = list => list[Math.floor(rand() * list.length)];
  const home = pick(clubs);
  let away = pick(clubs);
  while (away === home) away = pick(clubs);
  const players = size === 'small' ? Math.floor(rand() * 9) : 30;
  const Teams = [];
  for (let i = 0; i < players; i++) Teams.push([i + 1, rand() < 0.5 ? home : away]);
  // Boundary times come up often so both sides of half time are exercised.
  const special = ['00:00', '45:00', '45:01', '90:00', '44:59', '46:00'];
  const time = () => {
    if (rand() < 0.3) return pick(special);
    const minute = Math.floor(rand() * 91);
    return minute === 90 ? '90:00' : `${String(minute).padStart(2, '0')}:${String(Math.floor(rand() * 60)).padStart(2, '0')}`;
  };
  const Passes = [], seen = new Set();
  const target = players < 2 ? 0 : size === 'small' ? Math.floor(rand() * 9) : 2000;
  for (let tries = 0; Passes.length < target && tries < target * 5; tries++) {
    const from = 1 + Math.floor(rand() * players);
    let to = 1 + Math.floor(rand() * players);
    if (to === from) to = (to % players) + 1;
    const at = time();
    if (seen.has(`${from}|${at}`)) continue;
    seen.add(`${from}|${at}`);
    Passes.push([from, at, to]);
  }
  return [{ Teams, Passes }];
}
